const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette=['#f9e2af','#89b4fa','#eba0ac'];
const dimensions=[
 {id:'political',name:'Political',icon:'◈',title:'Political framing',labels:['Policy supportive','Mixed / descriptive','Policy critical'],description:'How the sampled articles frame this policy.'},
 {id:'people',name:'People',icon:'♙',title:'Whose voices lead?',labels:['Public officials','Experts & institutions','Affected residents'],description:'The primary voice quoted in each article. Click a group to see who is heard.'},
 {id:'language',name:'Language',icon:'文',title:'One story, across languages',labels:['English','Hindi','Regional'],description:'Coverage grouped by article language.'},
 {id:'ownership',name:'Ownership',icon:'▦',title:'Who is behind the reporting?',labels:['Media group','Independent','Public service'],description:'The organisations behind the sampled publishers.'},
 {id:'government',name:'Government',icon:'⌂',title:'Government-alignment signals',labels:['Supportive framing','Descriptive framing','Scrutinising framing'],description:'Observed treatment of the government response in these articles, with supporting excerpts.'},
 {id:'emotion',name:'Emotion',icon:'◉',title:'The emotional temperature',labels:['Measured','Emotive','High intensity'],description:'Tone and emotional intensity across the sampled headlines.'},
 {id:'gaps',name:'Coverage gaps',icon:'◫',title:'What made it into the story?',labels:['All 3 contexts','2 contexts','1 context'],description:'Three context points tracked across this story’s articles.'},
 {id:'evidence',name:'Evidence',icon:'◇',title:'Look beneath the headline',labels:['Primary document','Named sources','Attribution limited'],description:'The strongest available evidence basis in each sample article. Inspect each media card for context.'}
];
const media=[
 {name:'The Public Ledger',abbr:'PL',lang:'English',owner:'Ledger Group',political:2,people:1,language:0,ownership:0,government:2,emotion:0,gaps:0,evidence:0},
 {name:'Jan Varta',abbr:'जव',lang:'Hindi',owner:'Varta Network',political:0,people:0,language:1,ownership:0,government:0,emotion:1,gaps:1,evidence:1},
 {name:'Civic Dispatch',abbr:'CD',lang:'English',owner:'Civic Cooperative',political:1,people:2,language:0,ownership:1,government:1,emotion:0,gaps:0,evidence:0},
 {name:'Bharat Bulletin',abbr:'BB',lang:'Hindi',owner:'Bulletin Media',political:0,people:0,language:1,ownership:0,government:0,emotion:2,gaps:2,evidence:2},
 {name:'Southern Notebook',abbr:'SN',lang:'Tamil',owner:'Notebook Trust',political:2,people:2,language:2,ownership:1,government:2,emotion:1,gaps:1,evidence:1},
 {name:'Openline News',abbr:'ON',lang:'English',owner:'Openline Collective',political:1,people:1,language:0,ownership:1,government:1,emotion:0,gaps:0,evidence:0},
 {name:'Nagar Times',abbr:'NT',lang:'Hindi',owner:'Varta Network',political:2,people:2,language:1,ownership:0,government:2,emotion:1,gaps:1,evidence:1},
 {name:'Coastline Daily',abbr:'കോ',lang:'Malayalam',owner:'Coastline Cooperative',political:1,people:2,language:2,ownership:1,government:1,emotion:0,gaps:1,evidence:1},
 {name:'Civic Radio',abbr:'CR',lang:'English',owner:'Civic Broadcasting Trust',political:0,people:0,language:0,ownership:2,government:1,emotion:0,gaps:2,evidence:1}
];
const stories=[
 {id:'metro',category:'Public policy',time:'24 min ago',title:'A new metro corridor. A different story in every headline.',short:'Who benefits, who pays, and whose neighbourhood changes?',summary:'A proposed city metro extension brings transport access, public spending and neighbourhood disruption into the same debate. Compare how nine sample newsrooms choose to tell it.',topic:'Metro expansion proposal',ids:[0,1,2,3,4,5,6,7,8],contexts:['Project costs','Resident concerns','Planning document'],common:'The proposal adds six stations and opens a public consultation.',disputed:'The projected completion date is presented as certain in one account and conditional in another.',unique:'A residents’ survey describes concerns about access during construction.',headlines:['The metro plan needs a closer look at costs','Metro expansion promises a faster daily commute','Six stations proposed; residents invited to respond','A breakthrough for city commuters','Families along the route ask who will be relocated','What the transport proposal actually says','Shopkeepers question the construction timetable','Local routes and last-mile access remain unresolved','Transport department outlines expansion proposal'],quotes:['The cost estimate excludes two land-acquisition components.','Officials say the corridor could reduce daily travel time.','Residents have 30 days to comment on the planning document.','A transformational new chapter for every commuter.','Families along the alignment have requested relocation details.','The proposal lists six stations and a consultation timetable.','Traders asked whether the market would remain accessible.','Last-mile services are not specified in the initial plan.','The department described the next steps in its consultation.']},
 {id:'economy',category:'Economy',time:'46 min ago',title:'A manufacturing incentive sparks a debate over jobs and costs.',short:'Job promises meet questions about spending and eligibility.',summary:'A fictional manufacturing incentive offers support to small producers. The coverage splits between employment expectations, implementation details and questions over who qualifies.',topic:'Manufacturing incentive',ids:[0,1,2,4,5,6],contexts:['Eligibility rules','Worker perspectives','Budget document'],common:'The proposal includes an application window for eligible small manufacturers.',disputed:'Job projections differ because reports use different assumptions.',unique:'One report interviews contract workers about job security.',headlines:['Incentive’s fiscal costs deserve scrutiny','Manufacturing proposal puts jobs at the centre','Eligibility rules explained for small producers','Contract workers seek clarity on job protections','A guide to the scheme’s budget document','Small workshops question application requirements'],quotes:['The budget note does not give a firm estimate of recurring costs.','Officials expect the incentive to encourage hiring.','Applicants must meet the stated size and registration criteria.','Workers asked whether the incentive covers permanent roles.','The document sets out an initial allocation and a review period.','Workshop owners said the application process needs clarification.']},
 {id:'environment',category:'Environment',time:'1 hr ago',title:'A river restoration plan puts livelihoods in the spotlight.',short:'Environmental gains, local voices and the missing baseline.',summary:'A draft river restoration project prompts discussion about water quality, riverbank livelihoods and implementation. Explore which voices and supporting documents appear across the sample.',topic:'River restoration project',ids:[0,2,4,5,7],contexts:['Water-quality data','Local livelihoods','Restoration plan'],common:'The draft proposes restoration along a selected stretch of the river.',disputed:'The speed of expected water-quality improvement remains uncertain.',unique:'Fishers describe seasonal access needs not covered in the summary document.',headlines:['River plan lacks a complete pollution baseline','Restoration consultation opens to local residents','Riverbank workers ask how access will change','Reading the draft restoration plan','Fishers seek a place in restoration discussions'],quotes:['Several monitoring locations are absent from the baseline.','The consultation invites comments from riverbank communities.','Workers rely on daily access to the same stretch of river.','The draft lists ecological work and a phased review process.','Fishers described seasonal requirements for landing access.']},
 {id:'technology',category:'Technology',time:'2 hrs ago',title:'A digital classroom pilot raises questions beyond the screen.',short:'Access, teacher training and the evidence behind the promise.',summary:'A fictional school technology pilot introduces classroom devices. Compare the emphasis on access, teacher preparation and the measurement of learning outcomes.',topic:'Digital classroom pilot',ids:[1,2,3,5,6,8],contexts:['Teacher training','Learning outcomes','Pilot guidelines'],common:'A selected group of schools will take part in the pilot.',disputed:'Reports differ on whether improved outcomes have already been demonstrated.',unique:'Teachers highlight the time needed for training and maintenance.',headlines:['Digital classrooms bring a new opportunity','Teachers seek training before the pilot begins','A game-changing future for every student','What the pilot guidelines say about outcomes','School staff ask who will maintain the devices','Education department explains pilot stages'],quotes:['Officials describe the pilot as a step toward wider access.','Teachers want protected time to learn the new tools.','Technology will transform every classroom overnight.','The guidelines call for an evaluation after the initial phase.','Staff said maintenance responsibilities remain unclear.','The department outlined the first rollout and review stages.']}
];
let state={story:'metro',lens:'political',group:null,category:'All stories',query:''};
const current=()=>stories.find(s=>s.id===state.story);
const lens=()=>dimensions.find(d=>d.id===state.lens);
const selectedMedia=()=>current().ids.map((id,i)=>({...media[id],id,index:i}));
const coverageGroups=[
 {label:'Supportive',className:'supportive'},
 {label:'Mixed',className:'mixed'},
 {label:'Critical',className:'critical'}
];
function coverageCounts(s){return coverageGroups.map((_,group)=>s.ids.filter(id=>media[id].government===group).length);}
function coverageSummary(s){const counts=coverageCounts(s);return `<div class="coverage-summary" aria-label="Coverage framing: ${counts[0]} supportive, ${counts[1]} mixed, ${counts[2]} critical"><div class="coverage-summary-top"><span>Coverage split</span><span>${s.ids.length} reports</span></div><div class="coverage-bar">${counts.map((count,i)=>count?`<i class="${coverageGroups[i].className}" style="--share:${count}" title="${count} ${coverageGroups[i].label.toLowerCase()} reports"></i>`:'').join('')}</div><div class="coverage-labels">${counts.map((count,i)=>`<span>${count} ${coverageGroups[i].label.toLowerCase()}</span>`).join('')}</div></div>`;}
function coverageBoard(s){const counts=coverageCounts(s);return `<section class="coverage-board" aria-labelledby="coverage-heading"><div class="coverage-board-head"><div><span class="coverage-kicker">Story coverage</span><h3 id="coverage-heading">How the reports frame it</h3></div><span>${s.ids.length} reports</span></div><p>Each segment represents a sampled report. Select a segment to inspect the reporting behind it.</p><div class="coverage-bar coverage-bar-large">${counts.map((count,i)=>count?`<button class="${coverageGroups[i].className}" data-coverage-group="${i}" style="--share:${count}" aria-label="Show ${count} ${coverageGroups[i].label.toLowerCase()} reports">${count} ${coverageGroups[i].label.toLowerCase()}</button>`:'').join('')}</div><div class="coverage-report-list">${s.ids.map((id,index)=>{const m=media[id],group=coverageGroups[m.government];return `<button data-coverage-group="${m.government}"><span class="coverage-report-index ${group.className}">${String.fromCharCode(65+index)}</span><span>${m.name}</span><small>${group.label}</small></button>`}).join('')}</div></section>`;}
function renderStories(){const list=stories.filter(s=>(state.category==='All stories'||s.category===state.category)&&(`${s.title} ${s.summary} ${s.category}`.toLowerCase().includes(state.query.toLowerCase())));$('#story-count').textContent=`${list.length} ${list.length===1?'story':'stories'}`;$('#stories').innerHTML=list.length?list.map(s=>{const v=storyVisuals[s.id];return `<button class="story-card ${s.id===state.story?'selected':''}" data-story="${s.id}" aria-pressed="${s.id===state.story}"><img class="story-card-image" src="${v.image}" alt="${v.alt} — illustrative" loading="lazy"><div class="story-card-content"><div class="card-meta"><span>${s.category}</span></div><h3>${s.title}</h3><p class="desc">${s.short}</p><span class="story-signal">${v.tag}</span>${coverageSummary(s)}<div class="card-bottom"><span>${s.ids.length} media sources</span><span>${new Set(s.ids.map(id=>media[id].political)).size} framing groups</span></div></div></button>`}).join(''):'<div class="empty-state">No sample stories match. Try another topic or clear your search.</div>';}
function chooseStory(id){if(!stories.some(s=>s.id===id))throw Error('Unknown story');state.story=id;state.group=null;renderStories();renderComparison();}
function chooseLens(id){if(!dimensions.some(d=>d.id===id))throw Error('Unknown dimension');state.lens=id;state.group=null;renderLens();}
function renderComparison(){const s=current(),v=storyVisuals[s.id];document.querySelector('.comparison-photo')?.remove();document.querySelector('.signal-tags')?.remove();document.querySelector('.coverage-board')?.remove();document.querySelector('.brief-label')?.remove();const figure=document.createElement('figure');figure.className='comparison-photo';figure.innerHTML=`<img src="${v.image}" alt="${v.alt}"><figcaption>Illustrative photo · <a href="${v.source}" target="_blank" rel="noopener noreferrer">${v.credit}</a> · <a href="${v.licenseUrl}" target="_blank" rel="noopener noreferrer">${v.license}</a> · cropped for layout</figcaption>`;document.querySelector('.story-head').prepend(figure);$('#story-meta').innerHTML=`<span class="category">${s.category}</span><span class="fixture">Fictional example</span>`;$('#story-title').textContent=s.title;$('#story-summary').textContent=s.summary;$('#story-summary').insertAdjacentHTML('afterend',`<div class="signal-tags" aria-label="Suggested lenses"><button data-lens="${v.recommended}">${v.tag}</button><button data-lens="language">${new Set(selectedMedia().map(m=>m.lang)).size} languages in the mix</button><button data-lens="evidence">${selectedMedia().filter(m=>m.evidence===0).length} link a primary document</button></div>${coverageBoard(s)}`);$('#source-avatars').innerHTML=selectedMedia().slice(0,3).map(m=>`<span>${m.abbr}</span>`).join('');$('#source-count').textContent=`${s.ids.length} articles · ${new Set(selectedMedia().map(m=>m.owner)).size} owner groups`;if($('#fact-room'))$('#fact-room').innerHTML=`<h3>Claims and context</h3><div class="fact-grid"><div class="fact-block"><span>Commonly reported</span><p>${s.common}</p></div><div class="fact-block"><span>Disputed</span><p>${s.disputed}</p></div><div class="fact-block"><span>Less widely covered</span><p>${s.unique}</p></div></div><p class="fact-foot">Open “Compare claims” for source context.</p>`;if($('#intent-status'))$('#intent-status').textContent='';renderLens();}
function renderLens(){const d=lens(),ms=selectedMedia();$('#lens-tabs').innerHTML=dimensions.map(x=>`<button role="tab" aria-selected="${x.id===d.id}" tabindex="${x.id===d.id?0:-1}" class="${x.id===d.id?'selected':''}" data-lens="${x.id}"><span aria-hidden="true">${x.icon}</span>${x.name}</button>`).join('');const counts=d.labels.map((_,i)=>ms.filter(m=>m[d.id]===i).length);const percentages=counts.map(n=>Math.round(n/ms.length*100));const legend=d.labels.map((v,i)=>`<button data-group="${i}" aria-pressed="${state.group===i}"><i class="swatch" style="--color:${palette[i]}"></i>${v} · ${counts[i]}</button>`).join('');let chart='';
 if(d.id==='language'){let pos=0;const grad=counts.map((n,i)=>{const start=pos;pos+=n/ms.length*100;return `${palette[i]} ${start}% ${pos}%`}).join(',');chart=`<div class="lang-layout"><div class="donut" style="background:conic-gradient(${grad})"><div class="donut-hole"><b>${new Set(ms.map(m=>m.lang)).size}</b>languages</div></div><div class="lang-rows">${d.labels.map((v,i)=>`<button class="lang-row" data-group="${i}"><span>${v}</span><span class="track"><i style="--color:${palette[i]};--size:${percentages[i]}%"></i></span><strong>${percentages[i]}%</strong></button>`).join('')}</div></div>`;}
 else if(d.id==='evidence'||d.id==='ownership'){chart=`<div class="evidence-grid">${d.labels.map((v,i)=>`<button class="evidence-tile" data-group="${i}" style="--color:${palette[i]}"><b>${counts[i]}<small style="font-size:13px"> / ${ms.length}</small></b><span>${v}</span></button>`).join('')}</div>`;}
 else if(d.id==='gaps'){chart=`<div class="gap-rows">${current().contexts.map((v,i)=>`<div class="gap-row"><span>${v}</span><div aria-label="${ms.filter(m=>2-m.gaps>=i).length} of ${ms.length} articles include this context">${ms.map(m=>`<i class="${2-m.gaps>=i?'on':''}"></i>`).join('')}</div></div>`).join('')}</div><div class="legend"><span style="font-size:10px;color:#6e7077">Each square is one article · teal = included</span></div>`;}
 else{chart=`<div class="spectrum">${d.labels.map((v,i)=>counts[i]?`<button title="${v}: ${counts[i]} of ${ms.length} articles" aria-label="Filter ${v}, ${percentages[i]} percent" class="${state.group===i?'chosen':''}" data-group="${i}" style="--color:${palette[i]};--size:${counts[i]}">${percentages[i]}%</button>`:'').join('')}</div>`;}
 $('#lens-viz').innerHTML=`<div class="lens-insight"><div class="insight-top"><div class="insight-title">${d.title}</div><span class="count-tag">${ms.length} articles</span></div><p class="insight-description">${d.description}</p>${chart}<div class="legend">${legend}</div></div>`;
 $('#media-title').textContent=`Media by ${{political:'political framing',people:'quoted voices',language:'language',ownership:'ownership',government:'government framing',emotion:'emotional tone',gaps:'coverage depth',evidence:'evidence basis'}[d.id]}`;$('#media-total').textContent=state.group===null?`${ms.length} sources`:`${counts[state.group]} of ${ms.length} sources`;$('#clear-filter').hidden=state.group===null;
 $('#media-groups').innerHTML=d.labels.map((v,i)=>{if(state.group!==null&&state.group!==i)return '';const members=ms.filter(m=>m[d.id]===i);return `<div class="media-group" style="--color:${palette[i]}"><div class="group-title"><span>${v}</span><span>${members.length} ${members.length===1?'source':'sources'}</span></div><div class="media-members">${members.length?members.map(m=>`<button class="media-item" data-media="${m.id}" aria-label="Inspect ${m.name} article"><span class="monogram" style="--tint:${palette[i]}18;--tone:${palette[i]}">${m.abbr}</span><span><span class="media-name">${m.name}</span><span class="media-meta" style="display:block">${m.lang} · View evidence</span></span></button>`).join(''):'<p class="media-meta" style="padding:12px">No articles in this group.</p>'}</div></div>`}).join('');$('#media-groups').style.gridTemplateColumns=state.group!==null?'1fr':'';
}
function openDialog(title,body){$('#dialog-eyebrow').textContent=title;$('#dialog-body').innerHTML=body;$('#detail-dialog').showModal();}
function inspectMedia(id){const m=selectedMedia().find(x=>x.id===id);if(!m)return;const s=current(),d=lens();openDialog('Source detail · fictional publisher',`<div style="display:flex;align-items:center;gap:12px;margin-bottom:15px"><span class="monogram" style="width:45px;height:45px;font-size:14px">${m.abbr}</span><div><strong>${m.name}</strong><div class="media-meta">${m.lang} · ${m.owner}</div></div></div><h2 class="dialog-title">${s.headlines[m.index]}</h2><p class="dialog-intro">An illustrative article in the “${s.topic}” comparison.</p><div class="detail-block"><h4>${d.title}</h4><span class="pill">${d.labels[m[d.id]]}</span><div class="quote-box">“${s.quotes[m.index]}”</div><p>This excerpt and its annotations were written for the demonstration.</p></div><div class="detail-block"><h4>Context included</h4>${s.contexts.map((c,i)=>`<span class="pill">${2-m.gaps>=i?'✓':'—'} ${c}</span>`).join('')}</div><div class="detail-block"><h4>Source and evidence</h4><p>${dimensions.find(x=>x.id==='evidence').labels[m.evidence]} · ${dimensions.find(x=>x.id==='ownership').labels[m.ownership]}. Fictional article written for this example.</p></div>`);}
function claimsDialog(){const s=current();openDialog('Claim comparison',`<h2 class="dialog-title">What agrees. What differs.</h2><p class="dialog-intro">An illustration of how attributed claims would appear for “${s.topic}”.</p><div class="claim"><span class="status">Commonly reported</span><p>${s.common}</p><small>Sample articles from ${selectedMedia().slice(0,3).map(m=>m.name).join(', ')}.</small></div><div class="claim contested"><span class="status">Disputed</span><p>${s.disputed}</p><small>Different assumptions must be preserved when summarising.</small></div><div class="claim"><span class="status">Less widely covered</span><p>${s.unique}</p><small>A distinct perspective can be useful without being independently corroborated.</small></div>`);}
function methodDialog(){openDialog('Our methodology',`<h2 class="dialog-title">How coverage is compared</h2><p class="dialog-intro">Each lens highlights a different part of the reporting: framing, quoted voices, language, ownership, tone, context or evidence.</p><div class="detail-block"><h4>Article-level analysis</h4><p>Framing is assessed for each article. Ownership and language provide additional context. Coverage gaps identify details to investigate across sources.</p></div><div class="detail-block"><h4>Sample and percentages</h4><p>Charts count the articles in the selected story. Each article has one primary category per lens. Rounded percentages can total 99% or 101%. Publisher and owner counts are shown separately.</p></div><div class="detail-block"><h4>Explore the sources</h4><p>Select a lens, choose a group, and open an article to inspect its excerpt and supporting context.</p></div><div class="detail-block"><h4>Prototype scope</h4><p>The headline cards use a fixed sample edition. The comparison uses fictional stories, publishers and authored annotations. Questions are matched locally to eight supported lenses. Live retrieval, AI analysis, transcription and scheduled updates are planned integrations.</p></div><div class="detail-block"><h4>Review and corrections</h4><p>Production assessments should include the sampled articles, collection time, evidence excerpts, methodology version, uncertainty and a correction process.</p></div>`);}
function extensionDialog(){openDialog('Browser companion · planned',`<h2 class="dialog-title">A wider view, wherever you read.</h2><p class="dialog-intro">The planned Chrome companion brings this comparison beside the article or news video you are already viewing.</p><div class="detail-block"><h4>01 · Choose a story</h4><p>Click the extension on a news article or supported video and confirm the content to analyse.</p></div><div class="detail-block"><h4>02 · Find related reporting</h4><p>Retrieve articles about the same event from selected media, then remove duplicate coverage.</p></div><div class="detail-block"><h4>03 · Compare through a lens</h4><p>Inspect claims, framing and evidence with the same interactive views you see on this page.</p></div><p class="dialog-intro" style="margin-top:15px">The extension is planned for a future release.</p><button class="primary" id="explore-from-dialog">Explore the page demo</button>`);}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.story){chooseStory(el.dataset.story);if(innerWidth<850)$('#lens').scrollIntoView({behavior:'smooth'});}else if(el.dataset.coverageGroup!==undefined){state.lens='government';state.group=Number(el.dataset.coverageGroup);renderLens();$('#lens').scrollIntoView({behavior:'smooth',block:'start'});}else if(el.dataset.lens){chooseLens(el.dataset.lens);}else if(el.dataset.group!==undefined){const n=Number(el.dataset.group);state.group=state.group===n?null:n;renderLens();}else if(el.dataset.media!==undefined){inspectMedia(Number(el.dataset.media));}else if(el.dataset.category){state.category=el.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===state.category));renderStories();const first=stories.find(s=>(state.category==='All stories'||s.category===state.category)&&(`${s.title} ${s.summary} ${s.category}`.toLowerCase().includes(state.query.toLowerCase())));if(first)chooseStory(first.id);}else if(el.dataset.modal==='method')methodDialog();else if(el.dataset.modal==='extension')extensionDialog();else if(el.id==='clear-filter'){state.group=null;renderLens();}else if(el.id==='close-dialog')$('#detail-dialog').close();else if(el.id==='claims-button')claimsDialog();else if(el.id==='explore-from-dialog'){$('#detail-dialog').close();$('#explore').scrollIntoView({behavior:'smooth'});}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;renderStories();});
$('#lens-tabs').addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();let i=dimensions.findIndex(d=>d.id===state.lens);i=e.key==='Home'?0:e.key==='End'?dimensions.length-1:(i+(e.key==='ArrowRight'?1:-1)+dimensions.length)%dimensions.length;chooseLens(dimensions[i].id);document.querySelector(`[data-lens="${state.lens}"]`).focus();});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
renderStories();renderComparison();
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'select_news_comparison',description:'Select a fictional demo news story and bias dimension and update the visible comparison.',inputSchema:{type:'object',properties:{story:{type:'string',enum:stories.map(s=>s.id)},dimension:{type:'string',enum:dimensions.map(d=>d.id)}},required:['story','dimension'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!stories.some(s=>s.id===input.story)||!dimensions.some(d=>d.id===input.dimension))throw Error('Invalid story or dimension');chooseStory(input.story);chooseLens(input.dimension);return {story:state.story,dimension:state.lens,articles:selectedMedia().length};}});}
